CREATE TABLE certificate_templates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(180) NOT NULL,
    event_id BIGINT,
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    width INT NOT NULL DEFAULT 842,
    height INT NOT NULL DEFAULT 595,
    orientation VARCHAR(20) NOT NULL DEFAULT 'LANDSCAPE',
    layout_json CLOB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_template_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL
);

CREATE INDEX idx_template_event ON certificate_templates(event_id);

